void Solver::rephase() {
    // 1. Reset the rephase counter.
    rephases = 0;

    // 2. Make the threshold shrink more gently (5% instead of 10%).
    threshold = static_cast<int>(threshold * 0.95);

    // 3. Increase the limit for the next rephase step.
    rephase_limit += 4096;          // a smaller step than the original +8192

    // 4. Adaptive phase‑saving:
    //    - Compute the average activity of all variables.
    //    - Variables with activity above the average keep their current saved polarity.
    //    - Variables with activity below the average have their polarity flipped.
    double avg_act = 0.0;
    for (int v = 1; v <= vars; ++v) avg_act += activity[v];
    avg_act /= vars;

    for (int v = 1; v <= vars; ++v) {
        if (activity[v] <= avg_act) {
            // flip the saved polarity for low‑activity variables
            saved[v] = -saved[v];
        }
        // high‑activity variables keep their saved polarity (no change)
    }

    // 5. Small random perturbation to avoid getting stuck in a bad polarity pattern.
    //    With a 10 % probability, randomly reassign the polarity of ~10 % of the variables.
    if (rand() % 100 < 10) {
        for (int v = 1; v <= vars; ++v) {
            if (rand() % 10 == 0) {
                saved[v] = (rand() & 1) ? 1 : -1;
            }
        }
    }
}
